struct ContactServices:RepairServices {
 const CommonStore* common=nullptr;const MilitaryState* military=nullptr;const MilitaryCatalog* commands=nullptr;const MilitaryAccess* access=nullptr;const NavalState* naval=nullptr;const NavalCatalog* ships=nullptr;
 Outcome<Location> resolved_location(const StableId& actor)const override{return common->resolved_location(actor);}
 Outcome<std::optional<ArmyTravelView>> active_army(const StableId& actor)const override{for(const auto& army:military->armies)if(army.status=="active"&&army.commander_actor_id==actor){ArmyTravelView view;view.commander_actor_id=actor;view.wallet_id=army.wallet_id;view.inventory_id=army.inventory_id;view.member_actor_ids=army.member_actor_ids;for(const auto& unit:military->military_units)if(unit.army_id==army.id)view.fit_actor_ids.insert(view.fit_actor_ids.end(),unit.fit.begin(),unit.fit.end());return {true,std::move(view),{}};}return {true,std::nullopt,{}};}
 Outcome<std::optional<VesselFleetTravelView>> vessel_fleet(const StableId& actor)const override{auto value=preview_naval_travel(*common,*military,*commands,*access,*naval,*ships,actor,true);if(!value.ok)return {false,{},value.error};if(!value.value)return {true,std::nullopt,{}};const auto& v=*value.value;return {true,VesselFleetTravelView{v.fleet_id,v.army_id,v.commander_actor_id,v.payer_wallet_id,v.travel_budget},{}};}
};
