int main(){try{check(naval_navigation_contact_repair_examples()==0,"navigation source and legacy codec gates");ContactFixture f;const auto people=f.military.military_units[0].member_ids;auto balance=f.common.wallet("army_wallet")->balance;auto contacts=take(probe_naval_contacts(f.common,f.military,f.mc,f.access,f.naval,f.ships,f.travel_state,f.travel,f.actual,{},{},{}));check(contacts.ordered_hits.size()==1,"actual original moving versus stationary contact");auto phase=f.step();auto movement=take(step_terrain_travel(f.common,f.travel_state,f.travel,f.actual,f.action_id,true));check(movement.execution.has_value()&&!movement.completed&&f.naval.vessels[0].integrity==5,"Travel commits real step before any wear");const auto full=*movement.execution;std::vector<TerrainExecution> executed{full};auto battle=take(install_naval_contact(f.common,f.military,f.mc,f.access,f.travel_state,f.naval,f.ships,contacts.ordered_hits[0],&phase,&executed,&f.geometry));check(f.naval.navigation.steps.size()==1&&f.naval.navigation.steps[0].interrupted&&f.naval.vessels[0].integrity==0,"actual contact final step wears to zero once");check(f.naval.battle.battles.size()==1&&f.naval.battle.battles[0].frame.id==battle&&validate_naval_tactical_frame(f.naval,f.ships,f.mc.battle_catalog.battlefields[0],f.naval.battle.battles[0].frame).ok,"new zero hull remains in legal real battle");check(f.common.action(f.action_id)&&f.common.wallet("army_wallet")->balance==balance-1&&f.military.military_units[0].member_ids==people,"battle builds before original action exit with one Travel charge and conserved personnel");const auto& fact=f.naval.navigation.steps[0];const auto& hit=contacts.ordered_hits[0].contact.contact;const auto anchor=hit.first.actor_id=="captain0"?hit.first.anchor.point:hit.second.anchor.point;check(fact.contact_source_id==f.naval.battle.contacts[0].id&&fact.uncut&&same_naval_navigation_execution(*fact.uncut,full)&&fact.movement.to_point.x==anchor.x&&fact.movement.to_point.y==anchor.y&&fact.movement.to_point.x!=full.to_point.x,"permanent source uses actual collision anchor and original successful uncut step");auto checked=validate_naval_navigation_execution(f.travel_state,f.travel,f.geometry,f.naval.navigation.voyages[0],{fact.movement,fact.uncut,fact.contact_source_id},5,&f.naval.battle.contacts[0]);check(checked.ok,"exact contact-truncated navigation source cold rederives");auto bad=fact.movement;bad.to_point.x=60;check(!validate_naval_navigation_execution(f.travel_state,f.travel,f.geometry,f.naval.navigation.voyages[0],{bad,fact.uncut,fact.contact_source_id},5,&f.naval.battle.contacts[0]).ok,"uncut endpoint cannot replace actual contact anchor");std::cout<<"NAVAL_NAVIGATION_CONTACT="<<checks<<" FAILURES=0 SCOPE=ACTUAL_DOMAIN_CONTACT_ZERO_HULL_ONLY\n";return 0;}catch(const std::exception& error){std::cerr<<"NAVAL_NAVIGATION_CONTACT_FAIL checks="<<checks<<" "<<error.what()<<'\n';return 1;}}
